import re
import pandas as pd

def normalize_key(k: str) -> str:
    """Normalize metric names."""
    k = k.strip()

    k = k.replace("Ap", "AP")
    k = k.replace("AP .", "AP")
    k = k.replace("AR .", "AR")
    k = k.replace(" ", "")
    k = k.replace("(M)", "_M").replace("(L)", "_L")
    
    # Convert AP.5 → AP50, AP.75 → AP75
    k = k.replace("AP.5", "AP50")
    k = k.replace("AP.75", "AP75")
    k = k.replace("AR.5", "AR50")
    k = k.replace("AR.75", "AR75")

    return k


def parse_block(text: str):
    """Parse one experiment text block into a dict."""
    data = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        
        label, metrics = line.split(":", 1)
        label = label.strip()
        entry = {}

        pattern = r"([A-Za-z0-9\.\(\) ]+?)\s*=\s*([0-9\.eE+-]+)"
        for key, val in re.findall(pattern, metrics):
            entry[normalize_key(key)] = float(val)

        data[label] = entry

    return data


