experiments = {
    "standard": experiment_1,
    "linf8": experiment_2,
    "linf4": experiment_3
}

# ------------------------------------------
# ✅ Parse all experiments into a DataFrame
# ------------------------------------------

rows = []

for exp_name, text in experiments.items():
    parsed = parse_block(text)
    
    for label, metrics in parsed.items():
        row = {"experiment": exp_name, "label": label}
        row.update(metrics)
        rows.append(row)

df = pd.DataFrame(rows)

# ------------------------------------------
# ✅ Save to CSV
# ------------------------------------------

df.to_csv("results.csv", index=False)

print("CSV saved as results.csv")
print(df.head())
